\label{Def:NuclearGelfandPair}
The couple $({\mathcal{S}},{\mathcal{S}}')$ that is formed by a topological vector space ${\mathcal{S}}$ and
its topological dual ${\mathcal{S}}'$ is called a \emph{nuclear Gelfand pair} if
\begin{enumerate}
\item ${\mathcal{S}}$ is nuclear and Montel
\cite{Grothendieck1955,Pietsch1972,Treves2006};
\item there exists a continuous and dense embedding $\iota:{\mathcal{S}}\to{\mathcal{S}}'$ that is
canonical, in the sense that
$\langle\iota\varphi,\psi\rangle=\langle\iota\psi,\varphi\rangle$ for all
$\varphi,\psi\in{\mathcal{S}}$.
\end{enumerate}
Unless stated otherwise, ${\mathcal{S}}'$ is endowed with its weak-$\ast$ topology.

\label{Def:CondPositiveDef}
Let $({\mathcal{S}}, {\mathcal{S}}')$ be a nuclear Gelfand pair and ${\mathcal{N}}_{{\boldsymbol{p}}}$ a
finite-dimensional subspace of ${\mathcal{S}}'$ spanned by ${\boldsymbol{p}}=(p_1,\dots,p_{N_0})$. Then, the continuous operator
${\mathrm{A}}: {\mathcal{S}} \to {\mathcal{S}}'$ is said to be {\em ${\boldsymbol{p}}$-conditionally positive-definite} if
\begin{align}
\label{Eq:CondPositiveDefinite}
\langle {\mathrm{A}} \varphi,\varphi\rangle > 0
\mbox{ for all }\varphi \in {\mathcal{S}}_{{\boldsymbol{p}}} \backslash\{0\}.
\end{align}
Likewise, ${\mathrm{B}}: {\mathcal{S}} \to {\mathcal{S}}'$ is said to be {\em positive-definite} if
\begin{align}
\label{Eq:PositiveDefinite}
\langle {\mathrm{B}} \varphi,\varphi\rangle > 0
\mbox{ for all }\varphi \in {\mathcal{S}} \backslash\{0\}.
\end{align}

\label{Def:AttainableNull}
Let $q$ be a continuous seminorm on ${\mathcal{S}}$. Its \emph{attainable null space} is
\begin{align*}
{\mathcal{N}}_q:=\big\{p\in{\mathcal{S}}':\ p=\textstyle\lim_{k}\chi_k\ \text{in}\ {\mathcal{S}}'
\ \text{for some}\ (\chi_k)\subset{\mathcal{S}}\ \text{with}\ q(\chi_k)\to0\big\}.
\end{align*}
For the seminorm induced by a positive-semi-definite operator ${\mathrm{B}}:{\mathcal{S}}\to{\mathcal{S}}'$, we write
${\mathcal{N}}_{{\mathrm{B}}}:={\mathcal{N}}_{|\cdot|_{{\mathrm{B}}}}$.

\label{Def:Intrinsic}
Let ${\mathrm{A}},{\mathrm{B}}:{\mathcal{S}}\to{\mathcal{S}}'$ be continuous, with ${\mathrm{A}}$ ${\boldsymbol{p}}$-conditionally positive-definite and ${\mathrm{B}}$ positive-definite, so that the Hilbert spaces ${\mathcal{H}}_{{\mathrm{A}}}$ and
$\dot{{\mathcal{H}}}_{{\mathrm{B}}}$ of \eqref{Eq:HA}  and \eqref{Eq:HB}  are well defined. 
Then, the pair $({\mathrm{A}},{\mathrm{B}})$ is a \emph{${\boldsymbol{p}}$-conditional Riesz pair} for $({\mathcal{S}},{\mathcal{S}}')$ if
\begin{enumerate}
\item[(i)] {\em Null-space matching}: ${\mathcal{N}}_{{\mathrm{B}}}={\mathcal{N}}_{{\boldsymbol{p}}}$; and
\item[(ii)] {\em Hilbert duality}: the map $\pi\,{\mathrm{A}}$ and the operator ${\mathrm{B}}$ extend to mutually inverse isometric
isomorphisms
\begin{align*}
\pi\,{\mathrm{A}}:\ {\mathcal{H}}_{{\mathrm{A}}}\ \longrightarrow\ \dot{{\mathcal{H}}}_{{\mathrm{B}}},
\qquad
{\mathrm{B}}:\ \dot{{\mathcal{H}}}_{{\mathrm{B}}}\ \longrightarrow\ {\mathcal{H}}_{{\mathrm{A}}}.
\end{align*}
\end{enumerate}

\label{Def:SplineAdmissible}
Let $({\mathcal{S}},{\mathcal{S}}')$ be a nuclear Gelfand pair. A continuous linear operator ${\mathrm{L}}: {\mathcal{S}} \to L_2$ with {\em normal operator} ${\mathrm{B}}={\mathrm{L}}^\ast \circ {\mathrm{L}}: {\mathcal{S}} \to L_2 \to {\mathcal{S}}'$
is said to be ${\boldsymbol{p}}$-admissible if
\begin{enumerate}
\item There exists some operator ${\mathrm{A}}: {\mathcal{S}} \to {\mathcal{S}}'$ (the {\em conditional inverse} of the normal operator ${\mathrm{B}}$) such that $({\mathrm{A}}, {\mathrm{B}})$ is a ${\boldsymbol{p}}$-conditional Riesz pair. 
\item The (homogeneous) Hilbert space $\dot{{\mathcal{H}}}_{\mathrm{L}}=\overline{({\mathcal{S}},\|{\mathrm{L}} \cdot\|_{L_2})}$ is isometrically isomorphic to $L_2$.
\end{enumerate}

\label{Thm:PracticalChecklist}
Let ${\mathrm{L}}:{\mathcal{S}}\to L_2$ be a continuous linear operator, and let
\begin{align*}
Q(\varphi)
:=
\sup_{\psi\in{\mathcal{S}}\backslash\{0\}}
\frac{|\langle\varphi,\psi\rangle|^2}{\|{\mathrm{L}}\psi\|_{L_2}^2}
\in[0,+\infty],
\qquad
\varphi\in{\mathcal{S}},
\end{align*}
denote the dual energy. The following four conditions are each necessary and, together,
sufficient for ${\mathrm{L}}$ to be ${\boldsymbol{p}}$-admissible.
\begin{enumerate}
\item \emph{(Injectivity)} ${\mathrm{L}}$ is injective on ${\mathcal{S}}$.
\item \emph{(Dense range)} ${\mathrm{L}}({\mathcal{S}})$ is dense in $L_2$; equivalently,
$\ker({\mathrm{L}}^\ast)=\{0\}$.
\item \emph{(Strict ${\boldsymbol{p}}$-conditional positivity)}
\begin{align*}
Q(\varphi)<\infty
\quad\Longleftrightarrow\quad
\varphi\in{\mathcal{S}}_{{\boldsymbol{p}}}.
\end{align*}
\item \emph{(Sharpness)}
\begin{align*}
\|{\mathrm{L}}\psi\|_{L_2}
=\sup_{\varphi\in{\mathcal{S}}_{{\boldsymbol{p}}}\backslash\{0\}}
\frac{|\langle\psi,\varphi\rangle|}{\sqrt{Q(\varphi)}},
\qquad
\psi\in{\mathcal{S}}.
\end{align*}
\end{enumerate}
When Conditions 1--4 hold, we have that ${\mathcal{N}}_{{\mathrm{B}}}={\mathcal{N}}_{{\boldsymbol{p}}}$ and that
$Q(\varphi)=|\varphi|^2_{\mathrm{A}}$ on ${\mathcal{S}}_{{\boldsymbol{p}}}$ for every admissible ${\mathrm{A}}$ in the norm
defined by \eqref{Eq:NormA}.

\label{Theo:NativeSpace}
A ${\boldsymbol{p}}$-admissible operator ${\mathrm{L}}: {\mathcal{S}} \to L_2$ admits a continuous extension
${\mathrm{L}}: {\mathcal{H}}_{\mathrm{L}} \to L_2$ that specifies its native space ${\mathcal{H}}_{\mathrm{L}}$.
This
space has the following properties.
\begin{enumerate}
\item ${\mathcal{H}}_{\mathrm{L}}$  is the Hilbert space induced by the inner product
\begin{align}
\label{Eq:InnerProd}\langle f, g\rangle_{{\mathcal{H}}_{\mathrm{L}}}=\langle {\mathrm{L}} f, {\mathrm{L}} g \rangle_{L_2}+\sum_{n=1}^{N_0} \langle \phi_n,f\rangle\langle \phi_n,g\rangle
\end{align}
where $({\boldsymbol{\phi}},{\boldsymbol{p}})$ is a biorthogonal system for ${\mathcal{N}}_{\boldsymbol{p}}$ with ${\boldsymbol{\phi}} \subset {\mathcal{S}}$ (universality); Item \ref{Item:NormEquiv} relaxes that condition.
\item \label{Item:DirectSum}Direct-sum decomposition: ${\mathcal{H}}_{\mathrm{L}}={\mathcal{H}}_{{\mathrm{L}}, {\boldsymbol{\phi}}} \oplus {\mathcal{N}}_{\boldsymbol{p}}$ with
\begin{align}
{\mathcal{H}}_{{\mathrm{L}}, {\boldsymbol{\phi}}}&=\{f \in {\mathcal{H}}_{\mathrm{L}}: {\boldsymbol{\phi}}(f)={\boldsymbol{0}}\}={\mathrm{L}}_{{\boldsymbol{\phi}}}^{-1}(L_2)\\
{\mathcal{N}}_{\boldsymbol{p}}&=\{f \in {\mathcal{H}}_{\mathrm{L}}: {\mathrm{L}} f=0\}={\rm span}\{p_n\}_{n=1}^{N_0}.
\end{align}
The primary Hilbert space ${\mathcal{H}}_{{\mathrm{L}}, {\boldsymbol{\phi}}}$ with
$\|f\|_{{\mathcal{H}}_{{\mathrm{L}}, {\boldsymbol{\phi}}}}=\|{\mathrm{L}} f\|_{L_2}$ is isomorphic to $L_2={\mathrm{L}}({\mathcal{H}}_{{\mathrm{L}}, {\boldsymbol{\phi}}})$, while ${\mathcal{N}}_{\boldsymbol{p}}$ is the effective null space of ${\mathrm{L}}$.
\item Continuous and dense embeddings (Hilbert--Gelfand property): ${\mathcal{S}} \overset{d}{\hookrightarrow} {\mathcal{H}}_{\mathrm{L}} \overset{d}{\hookrightarrow}  {\mathcal{S}}'$. In particular, this enables us to specify ${\mathcal{H}}_{\mathrm{L}}$ as ${\mathcal{H}}_{{\mathrm{L}}}=\overline{({\mathcal{S}},\|\cdot\|_{{\mathcal{H}}_{\mathrm{L}}} )}$.
\item \label{Item:NormEquiv}Equivalent norms and topologies: As a set, ${\mathcal{H}}_{\mathrm{L}}$ is independent of the choice of biorthogonal system $({\boldsymbol{\phi}}, {\boldsymbol{p}})$ subject to the constraint $\phi_1, \cdots,\phi_{N_0} \in {\mathcal{H}}'_{\mathrm{L}}$. The norms induced by such systems are 
all topologically equivalent.


\item \label{Item:ExplicitRep} Explicit representation: For any $f \in {\mathcal{H}}_{\mathrm{L}}$, there exist some unique $w \in L_2$, $f^\ast \in {\mathcal{H}}'_{{\mathrm{L}}, {\boldsymbol{\phi}}}={\mathrm{L}}^\ast(L_2)$ and $p \in {\mathcal{N}}_{{\boldsymbol{p}}}$ such that
\begin{align}
\label{Eq:Sumdecomp1}
f&={\mathrm{A}}_{{\boldsymbol{\phi}}} \{f^\ast \}+ p={\mathrm{L}}_{{\boldsymbol{\phi}}}^{-1}\{ w\} + p
\end{align}
with $w={\mathrm{L}} f$, $f^\ast=({\mathrm{L}}^\ast{\mathrm{L}})\{ f\}$ and $p={\mathrm{R}}_{{\boldsymbol{p}}}{\mathrm{R}}_{{\boldsymbol{\phi}}}\{f\}$ where the linear operators 
${\mathrm{L}}_{{\boldsymbol{\phi}}}^{-1}: L_2 \to {\mathcal{H}}_{\mathrm{L}}$ and ${\mathrm{A}}_{{\boldsymbol{\phi}}}
: {\mathcal{H}}'_{{\mathrm{L}}}\to {\mathcal{H}}_{\mathrm{L}}$ are defined by \eqref{Eq:gInverse} and \eqref{Eq:Aphi}, respectively. 
\item \label{Item:RieszMaps}Explicit Riesz maps:
\begin{align}
{\mathrm{J}}_{{\mathcal{H}}_{\mathrm{L}}}&={\mathrm{L}}^\ast {\mathrm{L}} + {\mathrm{R}}_{{\boldsymbol{\phi}}}: {\mathcal{H}}_{\mathrm{L}} \to {\mathcal{H}}_{\mathrm{L}}'\\
{\mathrm{J}}_{{\mathcal{H}}'_{\mathrm{L}}}&={\mathrm{J}}_{{\mathcal{H}}_{\mathrm{L}}}^{-1}={\mathrm{A}}_{{\boldsymbol{\phi}}} + {\mathrm{R}}_{{\boldsymbol{p}}}: {\mathcal{H}}'_{\mathrm{L}} \to {\mathcal{H}}_{\mathrm{L}}\\
{\mathrm{J}}_{{\mathcal{H}}_{\mathrm{A}}}&={\mathrm{A}}_{{\boldsymbol{\phi}}}: {\mathcal{H}}_{\mathrm{A}} \to {\mathcal{H}}'_{\mathrm{A}}={\mathcal{H}}_{{\mathrm{L}},{\boldsymbol{\phi}}}.
\end{align}
\item Homogeneous part of the space:
\begin{align}
\dot{{\mathcal{H}}}_{{\mathrm{B}}}=\overline{({\mathcal{S}},\|{\mathrm{L}}\cdot\|_{L_2}) }={\mathcal{H}}_{\mathrm{L}}/{\mathcal{N}}_{\boldsymbol{p}}\cong {\mathcal{H}}_{{\mathrm{L}}, {\boldsymbol{\phi}}}.\end{align}
This quotient space is isometric to ${\mathcal{H}}'_{{\mathrm{L}},{\boldsymbol{\phi}}}={\mathcal{H}}_{\mathrm{A}}=\overline{({\mathcal{S}}_{\boldsymbol{p}},|\cdot|_{{\mathrm{A}}}) }$ with the corresponding Riesz map being $\pi {\mathrm{A}}=\pi {\mathrm{A}}_{{\boldsymbol{\phi}}}: {\mathcal{H}}_{\mathrm{A}} \to \dot{{\mathcal{H}}}_{{\mathrm{B}}}$. Unlike ${\mathcal{H}}_{{\mathrm{L}}, {\boldsymbol{\phi}}}$, the structure of $\dot{{\mathcal{H}}}_{{\mathrm{B}}}={\mathcal{H}}_{\mathrm{L}}/{\mathcal{N}}_{\boldsymbol{p}}$ and ${\mathcal{H}}_{\mathrm{A}}=({\mathcal{H}}_{\mathrm{L}}/{\mathcal{N}}_{\boldsymbol{p}})'$ (core) is independent of ${\boldsymbol{\phi}}$.
\end{enumerate}

\label{Prop:RangeA}
Let ${\mathrm{L}}$ be ${\boldsymbol{p}}$-admissible with conditional inverse ${\mathrm{A}}$ of the normal operator
${\mathrm{B}}={\mathrm{L}}^\ast{\mathrm{L}}$, extended by continuity to ${\mathrm{A}}: {\mathcal{H}}'_{\mathrm{L}} \to {\mathcal{S}}'$. Let us
further assume that ${\mathrm{A}}$ is {\em consistent}, in the sense that
\begin{align}
\label{Eq:Consistency}
({\mathrm{L}}^\ast{\mathrm{L}})\{{\mathrm{A}} \varphi\}=\varphi \quad \mbox{for every } \varphi \in {\mathcal{S}} \mbox{ such
that } {\mathrm{A}}\{\varphi\} \in {\mathcal{H}}_{\mathrm{L}},
\end{align}
where $({\mathrm{L}}^\ast{\mathrm{L}}): {\mathcal{H}}_{\mathrm{L}} \to {\mathcal{H}}_{{\mathrm{A}}}$ is the extension of
Item \ref{Item:RieszMaps} of Theorem \ref{Theo:NativeSpace}. Then,
\begin{align}
\label{Eq:Afprop}
{\mathrm{A}}\{\nu\} \in {\mathcal{H}}_{\mathrm{L}}
\quad \Leftrightarrow \quad
\nu \in {\mathcal{H}}_{{\mathrm{A}}}={\mathrm{L}}^\ast(L_2)
\quad \Leftrightarrow \quad
{\boldsymbol{p}}(\nu)={\boldsymbol{0}} .
\end{align}
Consequently, every $f \in {\mathcal{H}}_{\mathrm{L}}$ has a unique decomposition
\begin{align}
\label{Eq:DecomposeAgostic}
f={\mathrm{A}}\{f^\ast\} + p, \qquad
f^\ast=({\mathrm{L}}^\ast{\mathrm{L}})\{f\}\in {\mathcal{H}}_{{\mathrm{A}}}, \quad p \in {\mathcal{N}}_{{\boldsymbol{p}}},
\end{align}
which is the counterpart of Item \ref{Item:ExplicitRep} of Theorem \ref{Theo:NativeSpace} that
does not refer to any biorthogonal system.

