\label{Def:AdmisPoints} Let ${\mathcal{H}}_{\mathrm{L}}$ be the native Hilbert space of a ${\boldsymbol{p}}$-admissible operator ${\mathrm{L}}$ with
${\boldsymbol{p}}=(p_1,\dots,p_{N_0})$.
We say that the linear measurement operator ${\boldsymbol{\nu}}=(\nu_m): {\mathcal{H}}_{\mathrm{L}} \to  \mathbb{R}^M$ is \emph{${\mathrm{L}}$-compatible} if
\begin{enumerate}
\item  the $\nu_m$ are linearly independent with $\nu_m \in {\mathcal{H}}_{\mathrm{L}}'$ (continuity) for all $m$;
\item the matrix ${\bf{P}}={\boldsymbol{\nu}}({\boldsymbol{p}}) \in  \mathbb{R}^{M \times N_0}$ with $[{\bf{P}}]_{m,n}=\langle \nu_m, p_n\rangle$ is of rank $N_0$. 
\end{enumerate}

\label{Theo:GeneralRepSemiHilbert}
Let ${\mathrm{L}}: {\mathcal{S}} \to L_2$ be a ${\boldsymbol{p}}$-admissible operator with native space ${\mathcal{H}}_{\mathrm{L}}$ and
conditional inverse ${\mathrm{A}}$, let ${\boldsymbol{\nu}}=(\nu_m): {\mathcal{H}}_{\mathrm{L}} \to  \mathbb{R}^M$ with $M>N_0$ be
${\mathrm{L}}$-compatible in the sense of Definition \ref{Def:AdmisPoints}, and let
$E:  \mathbb{R}^M \times  \mathbb{R}^M \to  \mathbb{R}_{\ge0}\cup \{+\infty\}$ be lower-semicontinuous, coercive, and
convex in its second argument. Then, for any fixed ${\bf{y}}\in  \mathbb{R}^M$ and $\lambda \in  \mathbb{R}_{\ge 0}$,
the solution of the optimization problem
\begin{align}
\label{Eq:GenericOptimizationProb2}
\arg \min_{f \in {\mathcal{H}}_{\mathrm{L}}} J(f|{\bf{y}},\lambda) \quad\mbox{ with }\quad J(f|{\bf{y}},\lambda)=E\big({\bf{y}}, {\boldsymbol{\nu}}(f)\big)+ \lambda \|{\mathrm{L}} f\|^2_{L_2}
\end{align}
is unique and admits the
linear parametrization 
\begin{align}
\label{Eq:f0lin2}
f_\lambda=\sum_{m=1}^{M-N_0} \tilde a_m \widetilde{\psi}_m +\sum_{n=1}^{N_0} b_{n} p_n,
\end{align}
with expansion coefficients $(\widetilde{{\boldsymbol{a}}},{\boldsymbol{b}})\in  \mathbb{R}^{M}$ and 
fixed basis functions $p_n\in {\mathcal{N}}_{\boldsymbol{p}}$ and $\widetilde{\psi}_m={\mathrm{A}}_{\widetilde{{\boldsymbol{\phi}}}}\{\widetilde{\nu}_m\}\in {\mathcal{H}}_{{\mathrm{L}},\widetilde{{\boldsymbol{\phi}}}}$, where
${\mathrm{A}}_{\widetilde{{\boldsymbol{\phi}}}}$ is the Riesz map ${\mathcal{H}}_{{\mathrm{A}}} \to {\mathcal{H}}'_{{\mathrm{A}}}={\mathcal{H}}_{{\mathrm{L}},\widetilde{{\boldsymbol{\phi}}}}$ 
and  $\widetilde{{\boldsymbol{\nu}}}=(\widetilde{\nu}_m)=\widetilde{{\bf{Q}}}^\mathsf{T} {\boldsymbol{\nu}}$
is the complementary measurement basis specified in Lemma \ref{Prop:DirectSum}. 
Alternatively, the solution has an overparametrized representation as
\begin{align}
\label{Eq:f0lin2b}
f_\lambda=\sum_{m=1}^{M} a_m \psi_m +\sum_{n=1}^{N_0} b_{n} p_n\quad  \mbox{ s.t. }\quad
{\bf{P}}^\mathsf{T} {\bf{a}}={\bf{0}}
\end{align}
with ${\boldsymbol{a}}\in  \mathbb{R}^{M}$ and $\psi_m={\mathrm{A}}\{\nu_m\}$. The connection between the two parametrizations is
 ${\bf{a}}=\widetilde{{\bf{Q}}}\widetilde{{\boldsymbol{a}}}$ and $\widetilde{{\boldsymbol{a}}}={\bf{Q}}^\mathsf{T} {\bf{a}}$ where the matrices $\widetilde{{\bf{Q}}}, {\bf{Q}} \in  \mathbb{R}^{M \times (M-N_0)}$ are specified in Lemma \ref{Prop:DirectSum}.

\label{Prop:DirectSum}
Let ${\boldsymbol{\nu}}=(\nu_1,\dots,\nu_M)$ be a vector of linear functionals with $\nu_m \in {\mathcal{H}}'_{\mathrm{L}}$
and let ${\boldsymbol{p}}=(p_1,\dots,p_{N_0})$ be a basis of ${\mathcal{N}}_{{\boldsymbol{p}}}$ such that the matrix
${\bf{P}}={\boldsymbol{\nu}}({\boldsymbol{p}}) \in  \mathbb{R}^{M \times N_0}$ is of rank $N_0$.
Then, one can always find three matrices $\widetilde{{\bf{P}}}\in  \mathbb{R}^{M \times N_0}$, ${\bf{Q}}\in  \mathbb{R}^{M \times (M-N_0)}$, and $\widetilde{ {\bf{Q}}} \in  \mathbb{R}^{M \times (M-N_0)}$ 
such that 
\begin{align}
\label{Eq:Biortho2}
\left[
\begin{array}{c}
 \widetilde{{\bf{Q}}}^\mathsf{T}\\
    \widetilde{{\bf{P}}}^\mathsf{T}
 \end{array}
\right] \left[
\begin{array}{cc}
 {{\bf{Q}}} &     {{\bf{P}}} 
 \end{array}
\right]
={\bf{I}}_M.
\end{align}
Based on these matrices, ${\boldsymbol{\nu}}$ has the unique, reversible decomposition
\begin{align}
\label{Eq:Decompnu}
{\boldsymbol{\nu}}
= {{\bf{Q}}} \widetilde{{\boldsymbol{\nu}}} + {{\bf{P}}} \widetilde{{\boldsymbol{\phi}}},
\end{align}
where
\begin{align}
\label{Eq:ReducedBasis}
\widetilde{{\boldsymbol{\nu}}}&=(\widetilde{\nu}_1,\dots, \widetilde{\nu}_{M-N_0})=\widetilde{{\bf{Q}}}^\mathsf{T}{\boldsymbol{\nu}}  \in ({\mathcal{N}}_{{\boldsymbol{\nu}}} \cap {\mathcal{H}}_{\mathrm{A}})^{M-N_0}\\
\label{Eq:ReducedBasis2}\widetilde{{\boldsymbol{\phi}}}&=(\widetilde{\phi}_1,\dots, \widetilde{\phi}_{N_0})=\widetilde{{\bf{P}}}^\mathsf{T}{\boldsymbol{\nu}}
\in ({\mathcal{N}}_{{\boldsymbol{\nu}}})^{N_0},
\end{align}
with $\widetilde{{\boldsymbol{\nu}}}({\boldsymbol{p}})={\bf{0}}$ (orthogonality) and $\widetilde{{\boldsymbol{\phi}}}({\boldsymbol{p}})=\widetilde{{\bf{P}}}^\mathsf{T}{\bf{P}}={\bf{I}}_{N_0}$ (biorthonormality).

Equipped with such a problem-specific biorthogonal system $(\widetilde{{\boldsymbol{\phi}}},{\boldsymbol{p}})$, we invoke Theorem \ref{Theo:NativeSpace} to decompose $f \in {\mathcal{H}}_{\mathrm{L}}$ as $f=\tilde f + \tilde p$ with $\tilde f \in {\mathcal{H}}_{{\mathrm{L}}, \widetilde{{\boldsymbol{\phi}}}}$ and $\tilde p=\sum_{n=1}^{N_0} b_n p_n \in {\mathcal{N}}_{\boldsymbol{p}}$. In this configuration, ${\boldsymbol{\nu}}={\bf{Q}} \widetilde{{\boldsymbol{\nu}}}+ {\bf{P}} \widetilde{{\boldsymbol{\phi}}}$ with $\widetilde{{\boldsymbol{\nu}}}=\widetilde{{\bf{Q}}}^\mathsf{T} {\boldsymbol{\nu}} \in {\mathcal{H}}_{\mathrm{A}}^{M-N_0}$ and $\widetilde{{\boldsymbol{\phi}}}=\widetilde{{\bf{P}}}^\mathsf{T} {\boldsymbol{\nu}}$ where the matrices ${\bf{P}},\widetilde{{\bf{P}}}\in  \mathbb{R}^{M \times N_0}$ and $\widetilde{{\bf{Q}}}, {\bf{Q}} \in  \mathbb{R}^{M \times (M-N_0)}$ satisfy the invertibility relation \eqref{Eq:Biortho2}. Consequently,
\begin{align*}
{\boldsymbol{\nu}}(f)=\big({\bf{Q}} \widetilde{{\boldsymbol{\nu}}}+ {\bf{P}} \widetilde{{\boldsymbol{\phi}}}\big)(\tilde f + \tilde p)={\bf{Q}}\widetilde{{\boldsymbol{\nu}}}(\tilde f)+ {\bf{P}} {\bf{b}}
\end{align*}
where we have made use of the underlying biorthogonality properties; namely, (i) $\widetilde{{\boldsymbol{\phi}}}(\tilde f)={\boldsymbol{0}}$  for all $\tilde f \in {\mathcal{H}}_{{\mathrm{L}}, \widetilde{{\boldsymbol{\phi}}}}$, (ii) $\widetilde{{\boldsymbol{\nu}}}(p)={\boldsymbol{0}}$  for all $p \in {\mathcal{N}}_{\boldsymbol{p}}$ (because $\widetilde{{\boldsymbol{\nu}}}({\boldsymbol{p}})=\widetilde{{\bf{Q}}}^\mathsf{T}{\boldsymbol{\nu}}({\boldsymbol{p}})=\widetilde{{\bf{Q}}}^\mathsf{T}{\bf{P}}={\bf{0}}$), and (iii) $\langle \widetilde{\phi}_n, \sum_{m=1}^{N_0} b_m p_m\rangle= b_n$. Since $\|{\mathrm{L}} f\|^2_{L_2}=\|{\mathrm{L}} \tilde f\|^2_{L_2}$, this enables us to rewrite the optimization problem \eqref{Eq:GenericOptimizationProb2} as
\begin{align}
\min_{(\tilde f, {\bf{b}})\in {\mathcal{H}}_{{\mathrm{L}}, \widetilde{{\boldsymbol{\phi}}}}\times   \mathbb{R}^{N_0}}& J(\tilde f, {\bf{b}}) \nonumber\\ \mbox{ where }&
J(\tilde f, {\bf{b}})=E\Big({\bf{y}}, {\bf{Q}}\widetilde{{\boldsymbol{\nu}}}(\tilde f)+ {\bf{P}} {\bf{b}}\Big) + \lambda \|{\mathrm{L}} \tilde f\|^2_{L_2}.\label{Eq:Jmin}
\end{align}
Next, we observe that the functional
${\bf{b}} \mapsto J(\tilde f, {\bf{b}})$ with $\tilde f$ fixed is lower-semi\-continuous (l.s.c.), coercive (because ${\bf{P}}$ is of full column rank) and convex on $ \mathbb{R}^{N_0}$.
Likewise, $\tilde f \mapsto J(\tilde f, {\bf{b}})$ with ${\bf{b}}$ fixed is l.s.c. (because of the continuity of ${\boldsymbol{\nu}}: {\mathcal{H}}\to  \mathbb{R}^M$), coercive and {\em strictly convex} on ${\mathcal{H}}_{{\mathrm{L}}, \widetilde{{\boldsymbol{\phi}}}}$ because of the presence of the second term ($L_2$-norm). This implies that the global functional $(\tilde f , {\bf{b}})\mapsto J(\tilde f, {\bf{b}})$ is l.s.c., coercive and strictly convex, which ensures that the minimizer of \eqref{Eq:Jmin} exists and is unique \cite{Ekeland1999}.

This minimizer is denoted by $(\tilde f_\lambda, {\bf{b}}_\lambda)$ and is such that
\begin{align}
{\bf{Q}}\widetilde{{\boldsymbol{\nu}}}(\tilde f_\lambda)+ {\bf{P}} {\bf{b}}_\lambda=
 \left[
\begin{array}{cc}
 {{\bf{Q}}}  &  {{\bf{P}}} 
 \end{array}
\right] \left[
\begin{array}{c}
\widetilde{{\boldsymbol{\nu}}}(\tilde f_\lambda)  \\
{\bf{b}}_\lambda 
 \end{array}
\right]
={\bf{z}}_0 \in  \mathbb{R}^M,
\end{align} which fixes the first term of the criterion to some constant $E({\bf{y}},{\bf{z}}_0)$. By exploiting the invertibility of the underlying matrix, we get that
\begin{align}
\left[
\begin{array}{c}
\widetilde{{\boldsymbol{\nu}}}(\tilde f_\lambda)  \\
{\bf{b}}_\lambda 
 \end{array}
\right]=
 \left[
\begin{array}{cc}
 {{\bf{Q}}}  &  {{\bf{P}}} 
 \end{array}
\right]^{-1} {\bf{z}}_0 =\left[
\begin{array}{c}
 \widetilde{{\bf{Q}}}^\mathsf{T} {\bf{z}}_0\\
    \widetilde{{\bf{P}}}^\mathsf{T} {\bf{z}}_0
 \end{array}
\right],
\end{align}
which directly yields ${\bf{b}}_\lambda=  \widetilde{{\bf{P}}}^\mathsf{T} {\bf{z}}_0 \in  \mathbb{R}^{N_0}$. As for $\tilde f_\lambda$, we identify it as the solution of the simpler generalized interpolation problem
\begin{align}
\tilde f_\lambda=\arg \min_{\tilde f \in {\mathcal{H}}_{{\mathrm{L}},\widetilde{{\boldsymbol{\phi}}}}} \|{\mathrm{L}} \tilde f\|_{L_2} \ \mbox{ s.t.} \ \  
\widetilde{{\boldsymbol{\nu}}}(\tilde f)= \widetilde{{\bf{Q}}}^\mathsf{T} {\bf{z}}_0 \in  \mathbb{R}^{M-N_0},
\label{Eq:geninterpol2}
\end{align}
where $\|{\mathrm{L}} \tilde f\|_{L_2}$ coincides with the norm of the Hilbert space ${\mathcal{H}}_{{\mathrm{L}},\widetilde{{\boldsymbol{\phi}}}}$ (see Theorem \ref{Theo:NativeSpace}, Item \ref{Item:DirectSum}). We can now invoke the Riesz representer Theorem \ref{Theo:MinNorm} to obtain the parametric form of the solution as
\begin{align}
\label{Eq:SolutionParam2}
\tilde f_{\lambda}={\mathrm{A}}_{\widetilde{{\boldsymbol{\phi}}}}\left\{\sum_{m=1}^{M-N_0} \tilde a_m \widetilde{\nu}_m\right\} =\sum_{m=1}^{M-N_0} \tilde a_m {\mathrm{A}}_{\widetilde{{\boldsymbol{\phi}}}}\{\widetilde{\nu}_m\}
\end{align}
where ${\mathrm{A}}_{\widetilde{{\boldsymbol{\phi}}}}$ is the Riesz map ${\mathcal{H}}_{\mathrm{A}} \to {\mathcal{H}}_{{\mathrm{L}},\widetilde{{\boldsymbol{\phi}}}}$, and where
$\tilde f^\ast_{\lambda}=\sum_{m=1}^{M-N_0} \tilde a_m \widetilde{\nu}_m$ is the Hilbert conjugate of
$\tilde f_{\lambda}$. Since $\widetilde{\psi}_m={\mathrm{A}}_{\widetilde{{\boldsymbol{\phi}}}}\{\widetilde{\nu}_m\}$, the
right-hand side of \eqref{Eq:SolutionParam2} is precisely the first sum of \eqref{Eq:f0lin2}. The
desired result is obtained by adding back the optimal null-space component
$\tilde p=\sum_{n=1}^{N_0} b_n p_n \in {\mathcal{N}}_{\boldsymbol{p}}$ with coefficient ${\bf{b}}_\lambda$.

To get the more standard overparametrized form \eqref{Eq:f0lin2b}, we make use of
Proposition \ref{Prop:RangeA}, which gives ${\mathrm{A}}\{\tilde f^\ast_\lambda\} \in {\mathcal{H}}_{\mathrm{L}}$ with
${\mathrm{A}}\{\tilde f^\ast_\lambda\}-{\mathrm{A}}_{\widetilde{{\boldsymbol{\phi}}}}\{\tilde f^\ast_\lambda\} \in {\mathcal{N}}_{{\boldsymbol{p}}}$;
the null-space coefficients ${\bf{b}}$ of \eqref{Eq:f0lin2b} therefore differ from those of
\eqref{Eq:f0lin2} by that component. We then note that 
$\tilde f^\ast_{\lambda}=\widetilde{{\bf{a}}}^\mathsf{T} \widetilde{{\boldsymbol{\nu}}}=\widetilde{{\bf{a}}}^\mathsf{T} \widetilde{{\bf{Q}}}^\mathsf{T}{\boldsymbol{\nu}}={\bf{a}}^\mathsf{T} {\boldsymbol{\nu}}$ where ${\bf{a}}=\widetilde{{\bf{Q}}} \widetilde{{\bf{a}}} \in  \mathbb{R}^M$. The required orthogonality condition ${\boldsymbol{p}}(\tilde f^\ast_{\lambda})=0$ is met implicitly because
${\bf{P}}^\mathsf{T}{\bf{a}}={\bf{P}}^\mathsf{T}\widetilde{{\bf{Q}}}\widetilde{{\bf{a}}}={\boldsymbol{0}}$. Conversely, we have that
$\widetilde{{\bf{a}}}={\bf{Q}}^\mathsf{T} {\bf{a}}$ if and only if ${\bf{P}}^\mathsf{T} {\bf{a}}={\bf{0}}$. The matrix form of these equivalences is
\begin{align}
{\bf{a}} = \left[
\begin{array}{c c}
 \widetilde{{\bf{Q}}}   &  \widetilde{{\bf{P}}}
 \end{array}
\right] \left[
\begin{array}{c}
\widetilde{{\bf{a}}}\\
 {\bf{0}}
 \end{array}
\right] \quad \Leftrightarrow \quad \left[
\begin{array}{c}
\widetilde{{\bf{a}}}\\
 {\bf{0}}
 \end{array}
\right] = \left[
\begin{array}{c}
{\bf{Q}}^\mathsf{T}\\
   {\bf{P}}^\mathsf{T}
 \end{array}
\right] {\bf{a}},
\end{align}
which comes as a direct consequence of \eqref{Eq:Biortho2}.

Since ${\bf{P}}$ is of full column rank $N_0$, there necessarily exists some complementary matrix ${\bf{Q}}\in  \mathbb{R}^{M \times (M-N_0)}$
such that  $[{\bf{Q}} \ \ {\bf{P}}] \in  \mathbb{R}^{M \times M}$ is invertible. We then set
$\left[
\begin{array}{c}
 \widetilde{{\bf{Q}}}^\mathsf{T}\\
    \widetilde{{\bf{P}}}^\mathsf{T}
 \end{array}
\right]=[{\bf{Q}} \ \ {\bf{P}}]^{-1}$ and expand \eqref{Eq:Biortho2} to get\begin{align}
\left[
\begin{array}{cc}
 \widetilde{{\bf{Q}}}^\mathsf{T}{\bf{Q}} & \widetilde{{\bf{Q}}}^\mathsf{T}{\bf{P}} \\
    \widetilde{{\bf{P}}}^\mathsf{T}{\bf{Q}} &  \widetilde{{\bf{P}}}^\mathsf{T}{\bf{P}}
 \end{array}
\right] = \left[\begin{array}{cc}
{\bf{I}}_{M-N_0} & {\bf{0}} \\
{\bf{0}} &  {\bf{I}}_{N_0}
 \end{array}
\right].
\label{Eq:InverseBiortho}
\end{align}
Next, we write \eqref{Eq:ReducedBasis} and \eqref{Eq:ReducedBasis2} in matrix form as
\begin{align}
\label{Eq:directsumRM}
\left[
\begin{array}{c}
\widetilde{{\boldsymbol{\nu}}}  \\
\widetilde{{\boldsymbol{\phi}}}  
 \end{array}
\right] = \left[
\begin{array}{c}
 \widetilde{{\bf{Q}}}^\mathsf{T}\\
    \widetilde{{\bf{P}}}^\mathsf{T}
 \end{array}
\right] {\boldsymbol{\nu}}.
\end{align}
This is a linear system that can be inverted to yield
\begin{align}
{\boldsymbol{\nu}}
= \left[
\begin{array}{c}
 \widetilde{{\bf{Q}}}^\mathsf{T}\\
    \widetilde{{\bf{P}}}^\mathsf{T}
 \end{array}
\right]^{-1} \left[
\begin{array}{c}
\widetilde{{\boldsymbol{\nu}}}  \\
\widetilde{{\boldsymbol{\phi}}}  
 \end{array}
\right] =
 \left[
\begin{array}{cc}
 {{\bf{Q}}}  &  {{\bf{P}}} 
 \end{array}
\right] \left[
\begin{array}{c}
\widetilde{{\boldsymbol{\nu}}}  \\
\widetilde{{\boldsymbol{\phi}}}  
 \end{array}
\right],
\end{align}
which proves  \eqref{Eq:Decompnu}.
Based on these definitions and on \eqref{Eq:InverseBiortho}, we get $\widetilde{{\boldsymbol{\nu}}}({\boldsymbol{p}})=\widetilde{{\bf{Q}}}^\mathsf{T}{\boldsymbol{\nu}}({\boldsymbol{p}})=\widetilde{{\bf{Q}}}^\mathsf{T}{\bf{P}}={\bf{0}}$ (${\boldsymbol{p}}$-orthogonality) and
$\widetilde{{\boldsymbol{\phi}}}({\boldsymbol{p}})=\widetilde{{\bf{P}}}^\mathsf{T}{\boldsymbol{\nu}}({\boldsymbol{p}})=\widetilde{{\bf{P}}}^\mathsf{T}{\bf{P}}={\bf{I}}_{N_0}$ (biorthogonality). Likewise, we have that
$ \widetilde{{\bf{Q}}}^\mathsf{T}{\bf{Q}}={\bf{Q}}^\mathsf{T} \widetilde{{\bf{Q}}}={\bf{I}}_{M-N_0}$ and 
$ {\bf{P}}^\mathsf{T} \widetilde{{\bf{P}}}=(\widetilde{{\bf{P}}}^\mathsf{T}{\bf{P}})^\mathsf{T}={\bf{I}}_{N_0}$.
